parameters.jsCode:
const agent = $json || {};
const ctx = $('Contexto Foodie').first().json || {};
const entry = $('Entrada Core').first().json || {};
const policy = ctx?.context?.reservationPolicy?.reminder || {};
const restaurant = ctx?.context?.restaurant || {};
const branches = Array.isArray(ctx?.context?.branches) ? ctx.context.branches : [];
const steps = Array.isArray(agent.intermediateSteps) ? agent.intermediateSteps : [];

function parseMaybeJson(value) {
  if (value === null || value === undefined) return {};
  if (typeof value === 'object') return value;
  if (typeof value !== 'string') return {};
  try { return JSON.parse(value); } catch {}
  const trimmed = value.trim();
  const firstBrace = trimmed.indexOf('{');
  const lastBrace = trimmed.lastIndexOf('}');
  if (firstBrace >= 0 && lastBrace > firstBrace) {
    try { return JSON.parse(trimmed.slice(firstBrace, lastBrace + 1)); } catch {}
  }
  return { raw: value };
}

function toolName(step) {
  return step?.action?.tool || step?.tool || step?.toolName || step?.name || '';
}

function toolInput(step) {
  return step?.action?.toolInput || step?.toolInput || step?.input || step?.args || {};
}

function observation(step) {
  return parseMaybeJson(step?.observation ?? step?.output ?? step?.result ?? step?.response);
}

function nested(obj, paths) {
  for (const path of paths) {
    let cur = obj;
    let ok = true;
    for (const part of path.split('.')) {
      if (cur && Object.prototype.hasOwnProperty.call(cur, part)) cur = cur[part];
      else { ok = false; break; }
    }
    if (ok && cur !== undefined && cur !== null && cur !== '') return cur;
  }
  return undefined;
}

function toBool(value) {
  return value === true || String(value ?? '').toLowerCase() === 'true';
}

function failed(obs) {
  const statusCode = Number(nested(obs, ['statusCode', 'response.statusCode']));
  if (Number.isFinite(statusCode) && statusCode >= 400) return true;
  if (obs?.success === false || obs?.ok === false) return true;
  if (obs?.error || obs?.errors) return true;
  return false;
}

function normalizedStatus(value) {
  return String(value ?? '').trim().toLowerCase().replace(/[\s-]+/g, '_');
}

function pendingFromStructuredPayment(obs, defaultPending) {
  const pendingRaw = nested(obs, [
    'paymentPending',
    'payment.pending',
    'order.paymentPending',
    'order.payment.pending',
    'data.paymentPending',
    'data.payment.pending',
    'data.order.paymentPending',
    'data.order.payment.pending'
  ]);

  if (pendingRaw !== undefined) return toBool(pendingRaw);

  const paidRaw = nested(obs, [
    'paid',
    'paymentPaid',
    'paymentConfirmed',
    'payment.paid',
    'payment.confirmed',
    'order.paid',
    'order.paymentPaid',
    'order.paymentConfirmed',
    'data.paid',
    'data.paymentPaid',
    'data.paymentConfirmed',
    'data.payment.paid',
    'data.payment.confirmed',
    'data.order.paid',
    'data.order.paymentPaid',
    'data.order.paymentConfirmed'
  ]);

  if (paidRaw !== undefined) return !toBool(paidRaw);

  const statusRaw = nested(obs, [
    'paymentStatus',
    'payment.status',
    'order.paymentStatus',
    'order.payment.status',
    'data.paymentStatus',
    'data.payment.status',
    'data.order.paymentStatus',
    'data.order.payment.status'
  ]);

  const status = normalizedStatus(statusRaw);

  if (['pending','pending_payment','awaiting_payment','awaiting_confirmation','unpaid','created'].includes(status)) return true;
  if (['paid','confirmed','approved','completed'].includes(status)) return false;

  return defaultPending;
}

function localMinusHours(date, time, hours) {
  if (!date || !time || !Number.isFinite(hours)) return '';
  const d = new Date(`${date}T${time}:00Z`);
  if (Number.isNaN(d.getTime())) return '';
  d.setUTCHours(d.getUTCHours() - hours);
  return d.toISOString().slice(0, 19);
}

const routedCode = String(agent.reservationCode || '').trim();
const routedPaymentRequired = agent.paymentRequired === true;
const routedPaymentPending = agent.paymentPending === true;
const routedPaymentType = String(agent.paymentType || '').trim();
const routedPaymentReference = String(agent.paymentReference || '').trim();
const routedPaymentStateKnown = agent.paymentStateKnown === true;

const base = {
  ...agent,
  syncReminder: false,
  reminderKey: '',
  channelId: entry.channelId || '',
  phone: entry.phone || '',
  fullName: '',
  reservationCode: routedCode,
  paymentRequired: routedPaymentRequired,
  paymentPending: routedPaymentPending,
  paymentType: routedPaymentType,
  paymentReference: routedPaymentReference,
  paymentStateKnown: routedPaymentStateKnown,
  paymentReason: routedPaymentStateKnown ? 'assistant_structured_decision' : '',
  branchId: '',
  branchName: '',
  timezone: entry.timezone || 'America/Argentina/Buenos_Aires',
  serviceDate: '',
  serviceTime: '',
  partySize: 0,
  scheduledAt: '',
  status: '',
  hoursBefore: Number(policy?.hoursBefore) || 0,
  partySizeFrom: Number(policy?.partySizeFrom) || 0,
  reminderChannel: String(policy?.channel || ''),
  restaurantName: restaurant?.name || '',
  configVersion: ctx?.configVersion ?? null,
  updatedAt: new Date().toISOString(),
  lastReason: 'no_reservation_operation'
};

let matched = null;
for (let i = steps.length - 1; i >= 0; i--) {
  const name = toolName(steps[i]);
  if ([
    'foodie_crear_reserva',
    'foodie_modificar_reserva',
    'foodie_cancelar_reserva',
    'foodie_gift_cards_crear_orden',
    'foodie_gift_cards_consultar_orden'
  ].includes(name)) {
    matched = steps[i];
    break;
  }
}

if (!matched) {
  return {
    json: {
      ...base,
      lastReason: routedPaymentStateKnown
        ? 'payment_metadata_from_structured_routing'
        : (routedCode ? 'reservation_metadata_from_structured_routing' : 'no_reservation_operation')
    }
  };
}

const name = toolName(matched);
const input = parseMaybeJson(toolInput(matched));
const obs = observation(matched);

if (failed(obs)) {
  return {
    json: {
      ...base,
      paymentRequired: false,
      paymentPending: false,
      paymentType: '',
      paymentReference: '',
      paymentStateKnown: false,
      paymentReason: '',
      lastReason: name.startsWith('foodie_gift_cards_')
        ? 'gift_card_operation_failed'
        : 'reservation_operation_failed'
    }
  };
}

if (name === 'foodie_gift_cards_crear_orden' || name === 'foodie_gift_cards_consultar_orden') {
  const orderId = String(
    nested(obs, [
      'orderId',
      'id',
      'order.id',
      'order.orderId',
      'data.orderId',
      'data.id',
      'data.order.id',
      'data.order.orderId',
      'result.orderId',
      'result.id'
    ]) ??
    input.orderId ??
    routedPaymentReference ??
    ''
  ).trim();

  const isCreate = name === 'foodie_gift_cards_crear_orden';

  const explicitRequiredRaw = nested(obs, [
    'paymentRequired',
    'payment.required',
    'order.paymentRequired',
    'order.payment.required',
    'data.paymentRequired',
    'data.payment.required',
    'data.order.paymentRequired',
    'data.order.payment.required'
  ]);

  const paymentRequired = explicitRequiredRaw === undefined
    ? true
    : toBool(explicitRequiredRaw);

  const paymentPending = paymentRequired
    ? pendingFromStructuredPayment(
        obs,
        isCreate ? true : (routedPaymentStateKnown ? routedPaymentPending : true)
      )
    : false;

  return {
    json: {
      ...base,
      reservationCode: '',
      paymentRequired,
      paymentPending,
      paymentType: 'gift_card',
      paymentReference: orderId,
      paymentStateKnown: true,
      paymentReason: isCreate ? 'gift_card_order_created' : 'gift_card_order_status',
      lastReason: isCreate ? 'gift_card_order_created' : 'gift_card_order_status_checked'
    }
  };
}

const op =
  name === 'foodie_crear_reserva' ? 'create' :
  name === 'foodie_modificar_reserva' ? 'update' :
  'cancel';

const code = String(
  nested(obs, [
    'code',
    'reservation.code',
    'data.code',
    'data.reservation.code',
    'result.code'
  ]) ??
  input.code ??
  routedCode ??
  ''
).trim();

if (!code) {
  return { json: { ...base, lastReason: 'reservation_code_missing' } };
}

const branchId = String(
  input.branchId ??
  nested(obs, [
    'branchId',
    'reservation.branchId',
    'data.branchId',
    'data.reservation.branchId'
  ]) ??
  ''
).trim();

const branch = branches.find(b => String(b?.id || '') === branchId) || null;
const timezone = branch?.timezone || entry.timezone || 'America/Argentina/Buenos_Aires';
const branchName = branch?.name || '';

const reminderEnabled =
  policy?.enabled === true &&
  String(policy?.channel || '').toLowerCase() === 'whatsapp';

const threshold = Number(policy?.partySizeFrom);
const hoursBefore = Number(policy?.hoursBefore);

if (op === 'cancel') {
  return {
    json: {
      ...base,
      syncReminder: true,
      reminderKey: `${entry.channelId || 'channel'}:${code}`,
      reservationCode: code,
      paymentRequired: false,
      paymentPending: false,
      paymentType: '',
      paymentReference: '',
      paymentStateKnown: true,
      paymentReason: 'reservation_cancelled',
      branchId,
      branchName,
      timezone,
      status: 'cancelled',
      hoursBefore: Number.isFinite(hoursBefore) ? hoursBefore : 0,
      partySizeFrom: Number.isFinite(threshold) ? threshold : 0,
      reminderChannel: String(policy?.channel || ''),
      lastReason: 'reservation_cancelled'
    }
  };
}

const serviceDate = String(
  input.serviceDate ??
  nested(obs, [
    'serviceDate',
    'reservation.serviceDate',
    'data.serviceDate',
    'data.reservation.serviceDate'
  ]) ??
  ''
);

const serviceTime = String(
  input.serviceTime ??
  nested(obs, [
    'serviceTime',
    'reservation.serviceTime',
    'data.serviceTime',
    'data.reservation.serviceTime'
  ]) ??
  ''
);

const partySize = Number(
  input.partySize ??
  nested(obs, [
    'partySize',
    'reservation.partySize',
    'data.partySize',
    'data.reservation.partySize'
  ])
);

const fullName = String(
  input.fullName ??
  nested(obs, [
    'fullName',
    'reservation.fullName',
    'data.fullName',
    'data.reservation.fullName'
  ]) ??
  ''
);

const requiredRaw = nested(obs, [
  'paymentRequired',
  'depositRequired',
  'requiresDeposit',
  'reservation.paymentRequired',
  'reservation.depositRequired',
  'reservation.requiresDeposit',
  'data.paymentRequired',
  'data.depositRequired',
  'data.requiresDeposit',
  'data.reservation.paymentRequired',
  'data.reservation.depositRequired',
  'data.reservation.requiresDeposit',
  'deposit.required',
  'payment.required'
]);

const pendingRaw = nested(obs, [
  'paymentPending',
  'depositPending',
  'reservation.paymentPending',
  'reservation.depositPending',
  'data.paymentPending',
  'data.depositPending',
  'data.reservation.paymentPending',
  'data.reservation.depositPending',
  'deposit.pending',
  'payment.pending'
]);

const pendingAmountRaw = nested(obs, [
  'pendingAmount',
  'deposit.pendingAmount',
  'payment.pendingAmount',
  'reservation.pendingAmount',
  'reservation.deposit.pendingAmount',
  'data.pendingAmount',
  'data.reservation.pendingAmount'
]);

const requiredByInput = toBool(input.paymentRequired);
const requiredByBackend =
  toBool(requiredRaw) ||
  (Number.isFinite(Number(pendingAmountRaw)) && Number(pendingAmountRaw) > 0);

const paymentRequired = requiredByInput || requiredByBackend || routedPaymentRequired;

let paymentPending = false;
if (paymentRequired) {
  if (pendingRaw !== undefined) {
    paymentPending = toBool(pendingRaw);
  } else if (routedPaymentRequired) {
    paymentPending = routedPaymentPending || op === 'create';
  } else {
    paymentPending = op === 'create';
  }
}

const paymentReason =
  requiredByBackend
    ? 'foodie_reservation_state'
    : requiredByInput
      ? 'assistant_tool_input'
      : routedPaymentRequired
        ? 'assistant_structured_decision'
        : '';

const qualifies =
  reminderEnabled &&
  Number.isFinite(threshold) &&
  Number.isFinite(hoursBefore) &&
  Number.isFinite(partySize) &&
  partySize >= threshold;

const paymentType = paymentRequired ? 'reservation' : '';
const paymentReference = paymentRequired ? code : '';
const paymentStateKnown = paymentRequired || pendingRaw !== undefined;

if (op === 'create' && !qualifies) {
  return {
    json: {
      ...base,
      reservationCode: code,
      paymentRequired,
      paymentPending,
      paymentType,
      paymentReference,
      paymentStateKnown,
      paymentReason,
      branchId,
      branchName,
      timezone,
      fullName,
      serviceDate,
      serviceTime,
      partySize: Number.isFinite(partySize) ? partySize : 0,
      reminderChannel: String(policy?.channel || ''),
      lastReason: 'reminder_not_required'
    }
  };
}

return {
  json: {
    ...base,
    syncReminder: true,
    reminderKey: `${entry.channelId || 'channel'}:${code}`,
    reservationCode: code,
    paymentRequired,
    paymentPending,
    paymentType,
    paymentReference,
    paymentStateKnown,
    paymentReason,
    branchId,
    branchName,
    timezone,
    fullName,
    serviceDate,
    serviceTime,
    partySize: Number.isFinite(partySize) ? partySize : 0,
    scheduledAt: qualifies ? localMinusHours(serviceDate, serviceTime, hoursBefore) : '',
    status: qualifies ? 'pending' : 'cancelled',
    hoursBefore: Number.isFinite(hoursBefore) ? hoursBefore : 0,
    partySizeFrom: Number.isFinite(threshold) ? threshold : 0,
    reminderChannel: String(policy?.channel || ''),
    lastReason: qualifies
      ? (op === 'create' ? 'reservation_created' : 'reservation_updated')
      : 'no_longer_meets_reminder_policy'
  }
};

const agent = $json || {};
const raw = String(agent.output ?? '').trim();
const marker = '__ROUTING__';

let reply = raw;
let parsedOk = false;
let routing = {
  intent: 'none',
  tag: '',
  targetTeam: '',
  handoffRequested: false,
  requiredDataComplete: false,
  event: {
    date: '',
    time: '',
    partySize: null,
    fullName: '',
    eventType: '',
    email: ''
  },
  reservation: {
    code: '',
    paymentRequired: false,
    paymentPending: false,
    branchId: '',
    roomId: '',
    preferredZone: '',
    preferredZoneName: '',
    zoneRequested: false,
    generalAvailabilityAccepted: false
  },
  payment: {
    required: false,
    pending: false,
    type: '',
    reference: ''
  }
};

const idx = raw.lastIndexOf(marker);
if (idx >= 0) {
  reply = raw.slice(0, idx).trim();
  let tail = raw.slice(idx + marker.length).trim();
  tail = tail.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();

  const applyParsed = (parsed) => {
    if (!parsed || typeof parsed !== 'object') return;
    parsedOk = true;
    routing = {
      ...routing,
      ...parsed,
      event: {
        ...routing.event,
        ...(parsed.event && typeof parsed.event === 'object' ? parsed.event : {})
      },
      reservation: {
        ...routing.reservation,
        ...(parsed.reservation && typeof parsed.reservation === 'object' ? parsed.reservation : {})
      },
      payment: {
        ...routing.payment,
        ...(parsed.payment && typeof parsed.payment === 'object' ? parsed.payment : {})
      }
    };
  };

  try {
    applyParsed(JSON.parse(tail));
  } catch {
    const first = tail.indexOf('{');
    const last = tail.lastIndexOf('}');
    if (first >= 0 && last > first) {
      try { applyParsed(JSON.parse(tail.slice(first, last + 1))); } catch {}
    }
  }
}

if (!reply) reply = 'Hubo un inconveniente al preparar la respuesta. Por favor, intentá nuevamente.';

const event = routing.event || {};
const partyRaw = event.partySize;
const partySize = partyRaw === null || partyRaw === '' || partyRaw === undefined
  ? null
  : Number(partyRaw);

const reservation = routing.reservation || {};
const payment = routing.payment || {};

const reservationCode = String(reservation.code || '').trim();
const reservationBranchId = String(reservation.branchId || '').trim();
const reservationRoomId = String(reservation.roomId || '').trim();
const preferredZone = String(reservation.preferredZone || '').trim();
const preferredZoneName = String(reservation.preferredZoneName || '').trim();
const zoneRequested = reservation.zoneRequested === true;
const generalAvailabilityAccepted = reservation.generalAvailabilityAccepted === true;


const hasGenericPaymentState =
  payment.required === true ||
  payment.pending === true ||
  Boolean(String(payment.type || '').trim()) ||
  Boolean(String(payment.reference || '').trim());

const paymentRequired = hasGenericPaymentState
  ? payment.required === true
  : reservation.paymentRequired === true;

const paymentPending = hasGenericPaymentState
  ? payment.pending === true
  : reservation.paymentPending === true;

const paymentType = String(
  payment.type ||
  (reservationCode && paymentRequired ? 'reservation' : '')
).trim();

const paymentReference = String(
  payment.reference ||
  (paymentType === 'reservation' ? reservationCode : '')
).trim();

return {
  json: {
    ...agent,
    output: reply,
    reply,
    routeIntent: String(routing.intent || 'none'),
    routeTag: String(routing.tag || ''),
    targetTeam: String(routing.targetTeam || ''),
    handoffRequested: routing.handoffRequested === true,
    requiredDataComplete: routing.requiredDataComplete === true,
    eventDate: String(event.date || ''),
    eventTime: String(event.time || ''),
    eventPartySize: Number.isFinite(partySize) ? partySize : null,
    eventFullName: String(event.fullName || ''),
    eventType: String(event.eventType || ''),
    eventEmail: String(event.email || ''),
    reservationCode,
    reservationBranchId,
    reservationRoomId,
    preferredZone,
    preferredZoneName,
    zoneRequested,
    generalAvailabilityAccepted,
    paymentRequired,
    paymentPending,
    paymentType,
    paymentReference,
    paymentStateKnown: hasGenericPaymentState || Boolean(reservationCode && (reservation.paymentRequired === true || reservation.paymentPending === true)),
    routingParseOk: parsedOk
  }
};
